local _,AUI=...
-- Original, data-only starters. Native slash handlers execute the user's saved
-- macros; opening this catalogue never performs a gameplay action.
local T={classes={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"}}
AUI.MacroTemplates=T
local examples={
 mouseover={WARRIOR="Taunt: pick up a loose enemy under your pointer without changing your selected target.",PALADIN="Blessing of Protection: protect the friendly unit under your pointer while retaining your current target.",HUNTER="Serpent Sting: apply your sting to an enemy under the pointer; check that it should not stay crowd controlled.",ROGUE="Blind: control an enemy under the pointer without switching your selected target.",PRIEST="Flash Heal: heal a friendly unit frame under the pointer without dropping your damage target.",SHAMAN="Healing Wave: heal the friendly unit under the pointer while keeping your target.",MAGE="Polymorph: control an enemy under the pointer without changing targets; normal creature restrictions still apply.",WARLOCK="Fear: control a hovered enemy while retaining your main target; consider where it may run.",DRUID="Rejuvenation: apply a heal over time to the friendly unit under the pointer."},
 focus={WARRIOR="Pummel: interrupt your focus while attacking another enemy. Range and stance requirements still apply.",PALADIN="Hammer of Justice: stun your focus without switching targets; immunity and range still apply.",HUNTER="Concussive Shot: slow your focus while attacking your current target.",ROGUE="Kick: interrupt your focus without losing your selected enemy.",PRIEST="Shackle Undead: refresh control on an undead focus while healing another unit.",SHAMAN="Earth Shock: interrupt your focus while keeping your current target; choose the intended rank.",MAGE="Counterspell: interrupt your focus without dropping your current target.",WARLOCK="Fear: refresh control on your focus while keeping another target selected.",DRUID="Entangling Roots: control a focus when the current terrain and creature rules allow it."},
 targettarget={WARRIOR="Taunt: select a friendly party member and act on the enemy they are targeting; only use when you intend to take threat.",PALADIN="Judgement: with a friendly party member selected, act on their enemy target.",HUNTER="Serpent Sting: attack a friendly party member's enemy target without changing your selected friendly unit.",ROGUE="Sinister Strike: attack a friendly party member's enemy target when in melee range.",PRIEST="Smite: keep your tank selected while casting at their enemy target.",SHAMAN="Lightning Bolt: keep a friendly unit selected while casting at their enemy target.",MAGE="Frostbolt: attack a friendly party member's enemy target while retaining the friendly selection.",WARLOCK="Shadow Bolt: attack a friendly party member's enemy target without selecting it first.",DRUID="Wrath: cast at your friendly target's enemy while keeping that friendly unit selected."},
 cursor={WARRIOR="Only use this starter if a learned ability actually opens a ground reticle. Ordinary melee attacks and shouts do not.",PALADIN="Consecration is placed at your feet, not with a reticle; @cursor will not move it. Use this only for a genuine ground-reticle ability.",HUNTER="Volley: place the area at the pointer without the extra placement click. Classic-style traps are placed at your feet and are not an equivalent example.",ROGUE="Ordinary rogue abilities do not provide a suitable ground-reticle example. Use another starter unless a learned ability explicitly uses a reticle.",PRIEST="Do not assume later-expansion reticle spells exist in Forever. Use this only with an actually learned ground-placement ability.",SHAMAN="Classic-style totems are placed by the player, not at a cursor reticle; this starter does not relocate them.",MAGE="Blizzard: start the area at the pointer without an extra click. Check the ground location before pressing it.",WARLOCK="Rain of Fire: place the area immediately at your pointer. This can break nearby crowd control.",DRUID="Hurricane: place the area immediately at your pointer; it still requires a valid ground location and range."},
 self={WARRIOR="Bloodrage is already self-only and does not need @player. Prefer a different starter for ordinary warrior attacks.",PALADIN="Flash of Light: heal yourself even while an enemy is selected.",HUNTER="Mend Pet already targets your pet; do not turn it into a player-target spell. Use the pet-control tools instead.",ROGUE="Vanish is already self-only and does not need @player. This starter is intended for spells that can choose a friendly target.",PRIEST="Flash Heal: heal yourself without changing your selected target.",SHAMAN="Healing Wave: heal yourself while retaining a selected enemy or ally.",MAGE="Remove Lesser Curse: remove a curse from yourself without changing targets.",WARLOCK="Demon Armor is already self-only and gains nothing from @player. Use this only for a genuinely targetable friendly ability.",DRUID="Rejuvenation: put your heal over time on yourself without changing targets."},
 modifier={WARRIOR="Example pair: Hamstring normally, Thunder Clap with Shift. This chooses one action per press; it does not cast both.",PALADIN="Example pair: Holy Light normally, Flash of Light with Shift. Replace both placeholders with spells you have learned.",HUNTER="Example pair: Arcane Shot normally, Concussive Shot with Shift.",ROGUE="Example pair: Sinister Strike normally, Gouge with Shift. Each keeps its normal facing/range requirements.",PRIEST="Example pair: Heal normally, Flash Heal with Shift.",SHAMAN="Example pair: Healing Wave normally, Lesser Healing Wave with Shift.",MAGE="Example pair: Frostbolt normally, Fireball with Shift.",WARLOCK="Example pair: Shadow Bolt normally, Searing Pain with Shift.",DRUID="Example pair: Healing Touch normally, Rejuvenation with Shift. Form restrictions remain."},
 helpharm={WARRIOR="The classic warrior kit has no ordinary targeted heal to pair here. A modifier starter is usually more useful.",PALADIN="Example pair: Flash of Light on a friendly target, Judgement on an enemy. Seals and normal spell requirements remain.",HUNTER="Mend Pet is pet-specific, not a general friendly-target heal. Prefer a pet tool or modifier starter.",ROGUE="The classic rogue kit has no ordinary targeted heal to pair here. Prefer mouseover, focus or modifier tools.",PRIEST="Example pair: Flash Heal on a friendly target, Smite on an enemy.",SHAMAN="Example pair: Healing Wave on a friendly target, Lightning Bolt on an enemy.",MAGE="Example pair: Remove Lesser Curse on a friendly target, Frostbolt on an enemy.",WARLOCK="Example pair: Detect Lesser Invisibility on a friendly target, Shadow Bolt on an enemy, if both are learned.",DRUID="Example pair: Healing Touch on a friendly target, Wrath on an enemy. Form rules still apply."},
 attack={WARRIOR="Heroic Strike: begin swinging even if the queued ability cannot currently be used. It remains a queued next-swing attack.",PALADIN="Judgement: keep auto-attacking while trying to use your ability.",HUNTER="Raptor Strike: start melee attacks for a deliberate melee action; this does not start ranged Auto Shot.",ROGUE="Sinister Strike: begin melee attacks even when you do not have enough energy for the ability.",PRIEST="This starts melee attacks and can break control; avoid attaching it to normal healing or ranged casts.",SHAMAN="Stormstrike, if learned: begin melee attacks even when the ability is unavailable.",MAGE="This starts melee attacks and can break Polymorph. It is usually unsuitable for your ranged spells.",WARLOCK="This starts melee attacks and can break control. It is not a substitute for a ranged attack command.",DRUID="Claw, if learned and in cat form: start melee swings while attempting the ability. Normal form requirements remain."},
 resurrection={WARRIOR="The classic warrior kit has no resurrection spell for this starter.",PALADIN="Redemption: resurrect the dead friendly unit under the pointer, or your dead friendly target.",HUNTER="Revive Pet is pet-specific; it does not resurrect other players. Do not use this player-resurrection condition for it.",ROGUE="The classic rogue kit has no resurrection spell for this starter.",PRIEST="Resurrection: act on a dead friendly unit frame without changing your selection.",SHAMAN="Ancestral Spirit: act on a dead friendly unit frame without changing your selection.",MAGE="The classic mage kit has no resurrection spell for this starter.",WARLOCK="Soulstone is not the same as directly casting a resurrection on a dead mouseover. Use its native rules.",DRUID="Rebirth: resurrect a dead friendly unit under the pointer. Reagent, cooldown and combat-resurrection restrictions still apply."},
 sequence={WARRIOR="Example learning exercise: Battle Shout, then Demoralizing Shout. You must press the key again for the next action; failures can stall it.",PALADIN="Example learning exercise: a seal, then Judgement. Do not assume the sequence adapts to cooldowns or your target.",HUNTER="Example learning exercise: Hunter's Mark, then Serpent Sting. Each action requires another press and can fail normally.",ROGUE="Sequences do not inspect combo points or choose finishers for you. A modifier or focus starter is often more reliable.",PRIEST="Example learning exercise: Power Word: Fortitude, then Inner Fire. Each successful step advances on a separate press.",SHAMAN="Sequences do not decide which totem or shock is best. Prefer separate binds for reactive gameplay.",MAGE="Example learning exercise: Arcane Intellect, then Frost Armor. Each requires another press; this is not a damage rotation.",WARLOCK="Example learning exercise: Corruption, then Curse of Agony. Failure or an existing effect can stall it; it is not a smart DoT manager.",DRUID="Sequences do not handle form changes or decide which heal is needed. Separate binds are usually more reliable."},
 cancelaura={WARRIOR="Only cancel a buff deliberately; removing Battle Shout normally makes you weaker. This is not an automatic buff choice.",PALADIN="Divine Shield: remove your immunity early when you deliberately need it to end. Cancelling is immediate and does not ask again.",HUNTER="Do not assume a later-expansion immunity or stance exists. Only enter an actually removable aura you intend to lose.",ROGUE="Stealth can be intentionally cancelled, but doing so exposes you. Use only when that is the intended action.",PRIEST="Only remove an aura intentionally; cancelling your own defensive buffs normally reduces survivability.",SHAMAN="Only enter a removable aura you intend to lose; this is not a totem-destruction or dispel command.",MAGE="Ice Block, if learned: leave the immunity early. Be certain you want incoming damage to resume.",WARLOCK="Only remove an aura intentionally; cancelling Demon Armor normally reduces survivability.",DRUID="For leaving a shapeshift form, /cancelform is clearer. Do not assume every form or buff behaves like an ordinary aura."},
}
local starters={
 {"mouseover","Mouseover spell","#showtooltip SPELL\n/cast [@mouseover,exists,nodead][] SPELL","Cast on the living unit under your pointer, otherwise use normal targeting. Add help or harm to the condition if it should only affect friends or enemies. It does not change your selected target."},
 {"focus","Focus spell / interrupt","#showtooltip SPELL\n/cast [@focus,exists,nodead][] SPELL","Use a living focus; without one, use normal targeting. Set your focus first. This never chooses a spell or decides whether an enemy cast should be interrupted."},
 {"targettarget","Target of target spell","#showtooltip SPELL\n/cast [@targettarget,harm,nodead][harm,nodead] SPELL","Use your target's living enemy target, falling back to your current living enemy. Useful when you keep a friendly tank selected. It does not automatically choose a safe enemy."},
 {"cursor","Ground spell at cursor","#showtooltip SPELL\n/cast [@cursor] SPELL","For a genuine ground-reticle spell, place it at your pointer immediately. This removes the second placement click, so check range, terrain and nearby crowd control before pressing."},
 {"self","Spell on yourself","#showtooltip SPELL\n/cast [@player] SPELL","For a spell that can target a friendly unit, explicitly choose yourself. Self-only spells already do this. A pet-specific spell cannot be converted into a player spell."},
 {"modifier","Shift chooses another spell","#showtooltip\n/cast [mod:shift] SHIFT SPELL; DEFAULT SPELL","Hold Shift for the first spell; otherwise use the default spell. Each key press still performs one allowed action. Check that a conflicting Shift keybind is not intercepting it."},
 {"helpharm","Friendly / enemy spell","#showtooltip\n/cast [help,nodead] FRIENDLY SPELL; [harm,nodead] HOSTILE SPELL","Use the friendly spell on a living ally or the hostile spell on a living enemy. It does not guess what an untargeted player wants, and it does not choose by health."},
 {"attack","Melee attack plus ability","#showtooltip SPELL\n/startattack\n/cast SPELL","Start melee auto-attacks while attempting the named ability. Useful for melee resource gaps. Starting attacks may break crowd control; this is not a ranged auto-shot command."},
 {"resurrection","Mouseover resurrection","#showtooltip SPELL\n/cast [@mouseover,help,dead][help,dead] SPELL","Use a dead friendly mouseover or a dead friendly selected target. Enter a real player-resurrection spell. Ordinary combat, reagent and cooldown requirements still apply."},
 {"sequence","Manual cast sequence","#showtooltip\n/castsequence reset=target SPELL ONE, SPELL TWO","Advance through these spells with separate presses. It cannot choose by cooldown, health or best damage; failed steps can stall. reset=target resets when your target changes."},
 {"cancelaura","Cancel an aura","/cancelaura AURA","Immediately remove the named removable aura. This is a deliberate loss of a buff, not an enemy dispel or an automatic decision. Replace AURA carefully before saving."},
}
local markers={{8,"Skull"},{7,"Cross"},{6,"Square"},{5,"Moon"},{4,"Triangle"},{3,"Diamond"},{2,"Circle"},{1,"Star"},{0,"Clear marker"}}
function T:Catalogue()
 if self.entries then return self.entries end
 local result={}
 for _,m in ipairs(markers)do
  local number,name=m[1],m[2]
  result[#result+1]={id="marker"..number,name=name,category="Markers",macroName=number==0 and "RUI Clear"or "RUI "..name,body="/tm [@mouseover,exists][@target,exists] "..(number==0 and "0"or "!"..number),utility=true,
   explanation=number==0 and "Clear the marker on your mouseover, otherwise your current target. Group permissions still apply."or "Mark your mouseover, otherwise your current target. Repeated presses keep this marker rather than toggling it off. Group permissions still apply."}
 end
 local pings={"Attack","Warning","On my way","Assist","Not a threat","Threat"}
 result[#result+1]={id="ping",name="Context ping",category="Pings",macroName="RUI Ping",body="/ping",utility=true,requiresPing=true,explanation="Let the native ping system choose its context at activation. Your group settings, permissions and ping cooldown remain in effect. Creating this macro sends no ping."}
 for id,name in ipairs(pings)do result[#result+1]={id="ping"..id,name=name.." ping",category="Pings",macroName="RUI Ping "..id,body="/ping [@target,exists] "..id,utility=true,requiresPing=true,explanation="Send the native "..name:lower().." ping on your current target. With no target this does nothing. Group restrictions and the native ping cooldown still apply. The numbered type is locale-independent."}end
 for _,entry in ipairs({
  {"reload","Reload UI","RUI Reload","/reload","Reload the interface when you activate this macro. Unsaved UI/editor state can be lost. Creating the macro does not reload anything."},
  {"focusset","Set focus","RUI Focus","/focus [@mouseover,exists][@target,exists]","Set your mouseover as focus, falling back to your current target. The focus-spell starters can then use it."},
  {"focusclear","Clear focus","RUI Clear Focus","/clearfocus","Clear your focus when you activate this macro."},
  {"lasttarget","Previous target","RUI Last Target","/targetlasttarget","Return to the unit you previously targeted. It does not select an enemy based on threat or health."},
  {"petattack","Pet attack","RUI Pet Attack","/petattack [@target,harm,nodead]","Order your pet to attack your living enemy target. Intended for a character with a controllable pet; this does not cast your own attack."},
  {"petfollow","Pet recall","RUI Pet Recall","/petpassive\n/petfollow","Set your pet passive and recall it. This intentionally changes its behavior until you choose another stance."},
 })do result[#result+1]={id=entry[1],name=entry[2],macroName=entry[3],body=entry[4],explanation=entry[5],category="Tools",utility=true}end
 for _,entry in ipairs(starters)do result[#result+1]={id=entry[1],name=entry[2],macroName="RUI Spell",body=entry[3],explanation=entry[4],category="Spell starters",examples=examples[entry[1]]}end
 self.entries=result;return result
end
function T:ClassExample(entry,class)
 return entry.examples and entry.examples[class]or "Choose a learned ability appropriate to this condition. Replace every capitalised placeholder with its exact localized name; the example is not a claim that your character has learned it."
end
function T:Available(entry)
 return not entry.requiresPing or C_Ping and type(C_Ping.SendMacroPing)=="function"or false
end
